"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[32290],{32290:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/murder-on-the-orient-express.png\\"\\n          title=\\"오리엔트 특급살인\\"\\n          author=\\"애거서 크리스티\\"\\n          publisher=\\"황금가지\\"\\n          publishedDate=\\"2013-05-27\\"\\n          isbn=\\"9788982737039\\"\\n          rating=4.5\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\n```에르퀼 푸아로```가 등장하는 대표 작품으로, 완벽하게 ```닫힌 공간```인 열차 안에서 살인사건이 일어난다.  \\n<br>\\n외부인의 침입 흔적이 전혀 없으며, 용의자 12명을 차례로 심문하지만 용의자 전원에게는 서로가 서로의 증인이 되어주는 완벽한 알리바이가 존재한다.  \\n그리고 범행 현장에서는 주인 없는 손수건, 파이프 클리너, 심지어 강도와 깊이가 제각각인 열두 개의 자상 등 서로 모순되는 단서들만 발견된다.  \\n용의자들의 완벽한 알리바이와 부자연스러운 살인 현장으로 사건은 미궁 속으로 빠지는 듯 했지만 결국 푸아로는 모든 진실을 밝힌다.  \\n<br>\\n하지만 푸아로는 진실을 숨긴 채 사건을 마무리한다.  \\n<br>\\n독자의 예상을 완벽하게 배신하는 동시에, ```누가 범인인가(Whodunit)```라는 질문을 넘어 <mark>왜 그들은 범인이 되어야만 했는가(Whydunit)</mark>라는 깊은 차원으로 이야기를 승화시킨다.  \\n<br>\\n만약 법이 제 역할을 하지 못할 때, 개인이 직접 정의를 집행하는 것은 과연 정당화될 수 있는가?"}')}}]);